create or replace function montra_private.request_initial_asset_quote() returns trigger language plpgsql security definer set search_path='' as $$ begin perform net.http_post(url:='https://wkulplqfmjbjgszgofva.supabase.co/functions/v1/montra-market-sync',headers:=jsonb_build_object('Content-Type','application/json','x-montra-job',(select decrypted_secret from vault.decrypted_secrets where name='montra_job_token')),body:=jsonb_build_object('asset_id',new.id),timeout_milliseconds:=20000); return new; end $$; revoke all on function montra_private.request_initial_asset_quote() from public,anon,authenticated; create trigger montra_initial_asset_quote after insert on public.montra_assets for each row when (new.quote_source <> 'manual') execute function montra_private.request_initial_asset_quote(); create trigger montra_changed_asset_quote after update of quote_source,gold_karat,symbol,market,currency on public.montra_assets for each row when (new.quote_source <> 'manual' and (new.quote_source,new.gold_karat,new.symbol,new.market,new.currency) is distinct from (old.quote_source,old.gold_karat,old.symbol,old.market,old.currency)) execute function montra_private.request_initial_asset_quote();